.catalog-filters {
    padding: 1.5rem;
    background: #fafafa;
    border-right: 1px solid #e0e0e0;
    height: 100%;
}

.catalog-filters h2 {
    margin: 0 0 1rem;
    font-size: 1.25rem;
    color: #333;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    font-size: 0.9rem;
    font-weight: 600;
    margin: 0 0 0.5rem;
    color: #555;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.filter-empty {
    color: #999;
    font-size: 0.85rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.3rem 0;
    cursor: pointer;
    font-size: 0.95rem;
}

.price-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
    color: #555;
}

.price-inputs input {
    padding: 0.4rem 0.6rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.6rem;
    background: #2a7ae2;
    color: #fff;
    border: none;
