toolArgs.file_text:
@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="page-btn"
                disabled="@(Page <= 1)"
                @onclick="() => ChangePage(Page - 1)">
            Previous
        </button>

        @foreach (var p in GetPageNumbers())
        {
            <button class="page-btn @(p == Page ? "active" : "")"
                    @onclick="() => ChangePage(p)">
                @p
            </button>
        }

        <button class="page-btn"
                disabled="@(Page >= TotalPages)"
                @onclick="() => ChangePage(Page + 1)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task ChangePage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != Page)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        // Show up to 7 page numbers centered around the current page
        const int maxVisible = 7;
        int start = Math.Max(1, Page - maxVisible / 2);
        int end = Math.Min(TotalPages, start + maxVisible - 1);
        start = Math.Max(1, end - maxVisible + 1);

        for (int i = start; i <= end; i++)
        {
